css:
.win{border-radius:3px}
.win.focused{border-color:rgba(224,40,30,.6)}
.win > .bar{height:32px;letter-spacing:.04em}
.licon .tile{border-radius:4px}
.dock,.pinned-strip .bub,.bub{border-radius:3px}
.menubar{letter-spacing:.06em}
.menubar,.dock{backdrop-filter:blur(18px) saturate(.9)}
.ka-plate{position:absolute;inset:-4%;background-size:cover;background-repeat:no-repeat;opacity:0;
  will-change:opacity,transform;animation:kaPlate 72s infinite both}
.ka-plate.p1{opacity:1;background-position:center 62%}
.ka-plate.p2{background-position:center 45%;animation-delay:18s}
.ka-plate.p3{background-position:center 38%;animation-delay:36s}
.ka-plate.p4{background-position:center 60%;animation-delay:54s}
@keyframes kaPlate{0%{opacity:0;transform:scale(1.08) translate3d(1%,.6%,0);animation-timing-function:ease-in-out}
  8%{opacity:1;animation-timing-function:linear}
  25%{opacity:1;animation-timing-function:ease-in-out}
  33%{opacity:0;transform:scale(1) translate3d(-1%,-.6%,0)}
  100%{opacity:0;transform:scale(1) translate3d(-1%,-.6%,0)}}
.ka-plate::after{content:'';position:absolute;inset:0;background:inherit;opacity:0;
  animation:kaTear 11s steps(1) infinite}
.ka-plate.p2::after{animation-duration:13s}.ka-plate.p3::after{animation-duration:9s}
@keyframes kaTear{0%{opacity:0}
  71%{opacity:1;clip-path:inset(38% 0 58% 0);transform:translateX(-46px);filter:saturate(2) hue-rotate(-12deg)}
  72%{opacity:1;clip-path:inset(62% 0 31% 0);transform:translateX(30px);filter:saturate(2) hue-rotate(-12deg)}
  73%{opacity:1;clip-path:inset(12% 0 85% 0);transform:translateX(-18px);filter:saturate(2) hue-rotate(-12deg)}
  74%{opacity:0}
  90%{opacity:1;clip-path:inset(78% 0 17% 0);transform:translateX(64px);filter:invert(1)}
  91%{opacity:0}}
.ka-veil{position:absolute;inset:0;
  background:radial-gradient(ellipse at 50% 42%,rgba(8,6,8,0) 30%,rgba(8,6,8,.7) 100%),
    linear-gradient(to bottom,rgba(8,6,8,.5),rgba(8,6,8,.18) 38%,rgba(8,6,8,.55))}
.ka-grain{position:absolute;inset:-100px;opacity:.13;mix-blend-mode:screen;
  animation:kaJitter .32s steps(3) infinite}
@keyframes kaJitter{0%{transform:translate(0,0)}33%{transform:translate(-28px,14px)}
  66%{transform:translate(18px,-22px)}100%{transform:translate(0,0)}}
